fetch('icon.xml').then(r => r.text()).then(xml => {
    const doc = new DOMParser().parseFromString(xml, "text/xml");
    const svgNode = doc.querySelector('svg_elements');
    if (!svgNode) return;

    svgNode.querySelectorAll('text').forEach(t => t.remove());

    const cStart = doc.querySelector('color_start')?.textContent || '#2563eb';
    const cEnd = doc.querySelector('color_end')?.textContent || '#1e1b4b';

    const svg = `${svgNode.innerHTML}`;

    const link = document.createElement('link');
    link.rel = 'icon'; link.type = 'image/svg+xml';
    link.href = 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
    document.head.appendChild(link);
}).catch(e => console.warn('Favicon XML not loaded.'));

body.script:
const CREDENTIALS = {
  username: 'sistapel',
  password: 'S1sAl3x!'
};

let currentLang = localStorage.getItem('alex_lang') || 'id';
let isDark = localStorage.getItem('alex_theme') === 'dark';

const i18n = {
  id: {
    tooltip: "Portal akses aman dan manajemen terpadu Alex. Masuk untuk mengelola data sistem secara terpusat.",
    authTitle: "Masuk ke Alex",
    authSubtitle: "Gunakan kredensial resmi untuk membuka instans sistem.",
    authError: "Username atau password tidak cocok.",
    authBtn: "Otorisasi Akses",
    statusReady: "Sistem Alex Siap",
    statusActive: "Sesi Sistapel Aktif",
    logout: "Keluar",
    modalTitle: "Syarat & Ketentuan Penggunaan",
    modalSmartTitle: "Klausul Khusus Aplikasi Alex",
    modalSmartDesc: "Aplikasi Alex mengelola autentikasi akun sistapel secara lokal pada memori peramban Anda. Aplikasi ini tidak mentransmisikan data kredensial, kunci, atau sesi pengguna ke peladen terpisah tanpa instruksi terkonfigurasi."
  },
  en: {
    tooltip: "Secure Alex portal & unified system gateway. Authenticate to manage local instances.",
    authTitle: "Sign in to Alex",
    authSubtitle: "Enter verified credentials to unlock system access.",
    authError: "Invalid username or password.",
    authBtn: "Authorize Access",
    statusReady: "Alex System Ready",
    statusActive: "Sistapel Session Active",
    logout: "Sign Out",
    modalTitle: "Terms of Use & Disclaimer",
    modalSmartTitle: "Alex App Context Clause",
    modalSmartDesc: "Alex processes sistapel authentication locally within your browser memory. Credentials and active states are not dispatched to third-party endpoints without direct configuration."
  }
};

function initApp() {
  applyTheme(isDark);
  applyLanguage(currentLang);
  startClock();
  checkActiveSession();
  lucide.createIcons();
}

function toggleTheme() {
  isDark = !isDark;
  localStorage.setItem('alex_theme', isDark ? 'dark' : 'light');
  applyTheme(isDark);
}

function applyTheme(dark) {
  if (dark) {
    document.documentElement.classList.add('dark');
    document.getElementById('theme-icon')?.setAttribute('data-lucide', 'sun');
  } else {
    document.documentElement.classList.remove('dark');
    document.getElementById('theme-icon')?.setAttribute('data-lucide', 'moon');
  }
  lucide.createIcons();
}

function toggleLanguage() {
  currentLang = currentLang === 'id' ? 'en' : 'id';
  localStorage.setItem('alex_lang', currentLang);
  applyLanguage(currentLang);
}

function applyLanguage(lang) {
  const t = i18n[lang];
  document.getElementById('lang-toggle').innerText = lang.toUpperCase();
  document.getElementById('tooltip-text').innerText = t.tooltip;
  document.getElementById('auth-title').innerText = t.authTitle;
  document.getElementById('auth-subtitle').innerText = t.authSubtitle;
  document.getElementById('auth-error-msg').innerText = t.authError;
  document.getElementById('btn-submit').querySelector('span').innerText = t.authBtn;
  document.getElementById('footer-status').innerText = sessionStorage.getItem('alex_auth') ? t.statusActive : t.statusReady;
  document.getElementById('btn-logout-text').innerText = t.logout;
  document.getElementById('modal-title').innerText = t.modalTitle;
  document.getElementById('modal-smart-title').innerText = t.modalSmartTitle;
  document.getElementById('modal-smart-desc').innerText = t.modalSmartDesc;
}

function togglePassVisibility() {
  const passInp = document.getElementById('inp-password');
  const eyeIcon = document.getElementById('pass-eye-icon');
  if (passInp.type === 'password') {
    passInp.type = 'text';
    eyeIcon.setAttribute('data-lucide', 'eye-off');
  } else {
    passInp.type = 'password';
    eyeIcon.setAttribute('data-lucide', 'eye');
  }
  lucide.createIcons();
}

function handleAuth(e) {
  e.preventDefault();
  const u = document.getElementById('inp-username').value.trim();
  const p = document.getElementById('inp-password').value;
  const errorBox = document.getElementById('auth-error');

  if (u === CREDENTIALS.username && p === CREDENTIALS.password) {
    errorBox.classList.add('hidden');
    sessionStorage.setItem('alex_auth', 'sistapel');
    revealDashboard();
  } else {
    errorBox.classList.remove('hidden');
  }
  lucide.createIcons();
}

function checkActiveSession() {
  if (sessionStorage.getItem('alex_auth') === 'sistapel') {
    revealDashboard();
  }
}

function revealDashboard() {
  document.getElementById('auth-card').classList.add('hidden');
  document.getElementById('active-card').classList.remove('hidden');
  document.getElementById('footer-status').innerText = i18n[currentLang].statusActive;
  lucide.createIcons();
}

function handleLogout() {
  sessionStorage.removeItem('alex_auth');
  document.getElementById('inp-password').value = '';
  document.getElementById('active-card').classList.add('hidden');
  document.getElementById('auth-card').classList.remove('hidden');
  document.getElementById('footer-status').innerText = i18n[currentLang].statusReady;
  lucide.createIcons();
}

function copySessionData() {
  navigator.clipboard.writeText('user: sistapel | role: admin | app: alex');
}

function startClock() {
  const clockEl = document.getElementById('clock-display');
  setInterval(() => {
    const d = new Date();
    clockEl.innerText = d.toTimeString().split(' ')[0];
  }, 1000);
}

function openTermsModal() {
  document.getElementById('terms-modal').classList.remove('hidden');
}

function closeTermsModal() {
  document.getElementById('terms-modal').classList.add('hidden');
}

window.addEventListener('DOMContentLoaded', initApp);
